import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Check every element in parallel; raise Bad for lowest-index bad element."""
    from concurrent.futures import Future, ThreadPoolExecutor, as_completed

    if not xs:
        return []

    results: list[int] = [0] * len(xs)
    errors: dict[int, Bad] = {}
    min_bad_idx: int = len(xs)

    with ThreadPoolExecutor() as executor:
        futures: dict[Future[int], int] = {
            executor.submit(check, x): i for i, x in enumerate(xs)
        }
        for future in as_completed(futures):
            idx = futures[future]
            try:
                results[idx] = future.result()
            except Bad as err:
                errors[idx] = err
                if idx < min_bad_idx:
                    min_bad_idx = idx
                    for f, j in futures.items():
                        if j > min_bad_idx:
                            f.cancel()

    if errors:
        raise errors[min(errors)]

    return results


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_all_even_success() -> None:
    assert all_even([0, 2, 4, 6, 8]) == [0, 2, 4, 6, 8]


def test_all_even_single_bad() -> None:
    with pytest.raises(Bad) as exc_info:
        all_even([2, 4, 5, 8])
    assert exc_info.value.n == 5


def test_all_even_lowest_index_bad() -> None:
    with pytest.raises(Bad) as exc_info:
        all_even([2, 7, 4, 3, 6, 9])
    assert exc_info.value.n == 7


def test_all_even_first_element_bad() -> None:
    with pytest.raises(Bad) as exc_info:
        all_even([1, 2, 4, 3])
    assert exc_info.value.n == 1


def test_all_even_last_element_bad() -> None:
    with pytest.raises(Bad) as exc_info:
        all_even([2, 4, 6, 9])
    assert exc_info.value.n == 9


def test_all_even_all_bad() -> None:
    with pytest.raises(Bad) as exc_info:
        all_even([3, 1, 5])
    assert exc_info.value.n == 3
